+            .startObject()
+            .startObject("settings")
+            .field("index.number_of_shards", numberOfShards)
+            .endObject()
+            .startObject("mappings");
+        builder.rawValue(OldMappingsIT.class.getResourceAsStream(file), XContentType.JSON);
+        builder.endObject().endObject();
