+    static InMemoryModuleFinder of(Set<String> missingModules, Path... entries) {
+        return new InMemoryModuleFinder(
+            Arrays.stream(entries)
+                .map(EmbeddedModulePath::descriptorFor)
+                .map(md -> filterRequires(md, missingModules))
+                .collect(
